public class ClickControl
extends ScreenControl {
    public static final ResourceLocation id = new ResourceLocation("webdisplaystogether:click");
    ControlType type;
    Vector2i coord;
    int button = -1;

    public ClickControl(ControlType type, Vector2i coord) {
        this(type, coord, 1);
    }

    public ClickControl(ControlType type, Vector2i coord, int button) {
        super(id);
        this.type = type;
        this.coord = coord;
        this.button = button;
    }

    public ClickControl(FriendlyByteBuf buf) {
        super(id);
        this.type = ControlType.values()[buf.readByte()];
        if (buf.readBoolean()) {
            this.coord = new Vector2i((ByteBuf)buf);
        }
        this.button = buf.readInt();
    }

    @Override
    public void write(FriendlyByteBuf buf) {
        buf.writeByte(this.type.ordinal());
        buf.writeBoolean(this.coord != null);
        if (this.coord != null) {
            this.coord.writeTo((ByteBuf)buf);
        }
        buf.writeInt(this.button);
    }

