public class OwnerControl
extends ScreenControl {
    public static final ResourceLocation id = new ResourceLocation("webdisplaystogether:set_owner");
    NameUUIDPair owner;

    public OwnerControl(NameUUIDPair pair) {
        super(id);
        this.owner = pair;
    }

    public OwnerControl(FriendlyByteBuf buf) {
        super(id);
        this.owner = new NameUUIDPair(buf);
    }

    @Override
    public void write(FriendlyByteBuf buf) {
        this.owner.writeTo(buf);
    }

    @Override
    public void handleServer(BlockPos pos, BlockSide side, ScreenBlockEntity tes, NetworkEvent.Context ctx, Function<Integer, Boolean> permissionChecker) throws MissingPermissionException {
        throw new RuntimeException("Cannot handle ownership theft packet from server");
    }

    @Override
    @OnlyIn(value=Dist.CLIENT)
    public void handleClient(BlockPos pos, BlockSide side, ScreenBlockEntity tes, NetworkEvent.Context ctx) {
        tes.getScreen((BlockSide)side).owner = this.owner;
    }
}

