public class GetSizeQuery
extends JSQueryHandler {
    public GetSizeQuery() {
        super("GetSize");
    }

    @Override
    public boolean handle(CefBrowser browser, CefFrame frame, JsonObject data, boolean persistent, CefQueryCallback callback) {
        WDBrowser wdBrowser;
        if (browser instanceof WDBrowser && (wdBrowser = (WDBrowser)browser).getSide() != null) {
            Vector2i sz = wdBrowser.getBe().getScreen((BlockSide)wdBrowser.getSide()).size;
            callback.success("{\"x\":" + sz.x + ",\"y\":" + sz.y + "}");
            return true;
        }
        callback.failure(404, "Screen has been removed.");
        return true;
    }
}

